// Pure technical metadata import. The only subprocess commands are Git blob reads,
// and the original frozen harness grade/summary. No prepare/start/choose/next/install/model.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {spawnSync} from 'node:child_process';import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url)),root=path.resolve(here,'../..'),mode=process.argv[2],canonical='880fc8ccd8d28a75e84e8bfd0ec90c58f657356a';
const hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const write=(name,value)=>fs.writeFileSync(path.join(here,name),JSON.stringify(value,null,2)+'\n',{flag:'wx'});
const read=file=>JSON.parse(fs.readFileSync(file,'utf8'));
function files(dir){if(!fs.existsSync(dir))return [];const rows=[];for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())rows.push(...files(p));else rows.push(p);}return rows;}
function inventory(){return files(root).filter(p=>!p.startsWith(here+path.sep)).sort().map(p=>({relative:path.relative(root,p).replaceAll('\\','/'),bytes:fs.statSync(p).size,sha256:hash(fs.readFileSync(p))}));}
function batches(){return ['blocking','expanded','continuous-supplement'].flatMap(kind=>files(path.join(root,kind,'runs')).filter(p=>path.basename(p)==='batch.json').map(file=>({kind,file,b:read(file)})));}
function discovery(){const all=batches(),reviews=['blocking','expanded','continuous-supplement'].flatMap(kind=>files(path.join(root,kind,'reviews')).filter(p=>p.endsWith('.json'))).flatMap(file=>{const r=read(file);return r.method==='independent_semantic_review'&&r.canonicalSha===canonical?[{file,sha256:hash(fs.readFileSync(file)),criteriaSha256:hash(JSON.stringify(r.criteria)),r}]:[];});const matched=[],external=[];
 for(const review of reviews){const possible=all.filter(q=>q.b.source.canonicalSha===canonical&&q.b.cases[review.r.variant]?.attempts.some(a=>a.attemptId===review.r.attemptId));if(!possible.length){external.push({file:review.file,sha256:review.sha256,variant:review.r.variant,attemptId:review.r.attemptId??null,status:review.r.status,reason:'No actual attempt; external review only, never grade.'});continue;}if(possible.length!==1)throw new Error('ambiguous batch');const q=possible[0],key=[canonical,review.r.variant,review.r.attemptId].join('|');if(matched.some(m=>m.key===key))throw new Error('duplicate independent reviews require explicit resolution, not overwrite');matched.push({...review,key,kind:q.kind,batchFile:q.file,attempt:q.b.cases[review.r.variant].attempts.find(a=>a.attemptId===review.r.attemptId)});}
 const missing=all.flatMap(q=>Object.entries(q.b.cases).flatMap(([variant,s])=>s.attempts.filter(a=>!matched.some(m=>m.key===[canonical,variant,a.attemptId].join('|'))).map(a=>({kind:q.kind,batchFile:q.file,variant,attemptId:a.attemptId,uuid:a.threadId,inputs:a.turns.length}))));return {all,matched,external,missing};}
function compact(d){return {actualReviews:d.matched.map(m=>({file:m.file,sha256:m.sha256,criteriaSha256:m.criteriaSha256,canonicalSha:m.r.canonicalSha,variant:m.r.variant,attemptId:m.r.attemptId,status:m.r.status,reviewer:m.r.reviewer,kind:m.kind,batchFile:m.batchFile,uuid:m.attempt.threadId,actualInputs:m.attempt.turns.length})),external:d.external,missing:d.missing};}
if(mode==='before'){
 const inv=inventory(),d=discovery();fs.mkdirSync(path.join(here,'before-batches'),{recursive:true});fs.mkdirSync(path.join(here,'original-reviews'),{recursive:true});
 for(const q of d.all){if(q.b.source.canonicalSha!==canonical)throw new Error('mixed canonical');const dir=path.join(here,'before-batches',q.kind,q.b.runId);fs.mkdirSync(dir,{recursive:true});fs.copyFileSync(q.file,path.join(dir,'batch.json'),fs.constants.COPYFILE_EXCL);const summary=path.join(q.b.recordRoot,'summary.json');if(fs.existsSync(summary))fs.copyFileSync(summary,path.join(dir,'summary.json'),fs.constants.COPYFILE_EXCL);}
 for(const m of d.matched)fs.copyFileSync(m.file,path.join(here,'original-reviews',m.r.variant+'-'+m.r.attemptId+'.json'),fs.constants.COPYFILE_EXCL);
 const cacheAndSource=d.all.map(q=>({kind:q.kind,batchFile:q.file,canonical:q.b.source,cacheRoot:q.b.cacheRoot,runtime:q.b.runtime.map(r=>{const git=spawnSync('git',['-C',q.b.source.repo,'show',`${canonical}:plugins/html-guide-kit/${r.relative}`],{encoding:null,maxBuffer:10485760,windowsHide:true});if(git.status!==0)throw new Error('source blob read failed');return {relative:r.relative,declared:r,actualSourceSha256:hash(git.stdout),actualMirrorSha256:hash(fs.readFileSync(path.join(q.b.mirror.root,'plugins/html-guide-kit',r.relative))),actualCacheSha256:hash(fs.readFileSync(path.join(q.b.cacheRoot,r.relative)))};})}));
 write('inventory-before.json',{recordedAt:new Date().toISOString(),root,canonicalSha:canonical,files:inv,cacheAndSource,scope:'All existing 0.1.9 reviewer/control/model record bytes outside this new provenance directory; original HOME/TEMP/auth are never copied.'});write('review-map-before.json',compact(d));write('subprocess-guard.json',{allow:['git -C <canonical repo> show <canonical>:plugins/html-guide-kit/<declared resource>','node <original same-kind harness.mjs> grade --batch <existing> --review <original>','node <original same-kind harness.mjs> summary --batch <existing>'],deny:'No model, installation, preparation, selection, input, repository edit, criterion edit, or old sealed version mutation.',scriptRawSha256:hash(fs.readFileSync(fileURLToPath(import.meta.url)))});console.log(JSON.stringify({mode,originalFiles:inv.length,actualReviews:d.matched.length,externalOnly:d.external.length,missing:d.missing}));
